/* RC8.6 quarterly management reports: pure calculation, no storage writes. */
function muReportDate(value){let s=String(value||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return '';let d=new Date(s+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===s?s:''}
