function muReportStable(value){if(Array.isArray(value))return '['+value.map(muReportStable).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+muReportStable(value[k])).join(',')+'}';return JSON.stringify(value)}
